arguments.command:
cd /tmp && mkdir -p stackalloc_nint_test && cd stackalloc_nint_test && dotnet new console --force -q && cat > Program.cs << 'EOF'
using System;

Span<nint> span = stackalloc nint[5];
for (int i = 0; i < span.Length; i++)
    span[i] = (nint)(i * 10);

for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"span[{i}] = {span[i]}");

Console.WriteLine($"nint size: {nint.Size} bytes");
EOF
dotnet run

